    expect(getResponseValue(rolesGetResponse, "roles.0.id"), 'value').not.toBeNull();
    expect(getResponseValue(rolesGetResponse, "roles.0.name"), 'roles.0.name').toBe("Administrator");
    expect(getResponseValue(rolesGetResponse, "roles.0.description"), 'roles.0.description').toBe("Administrators");
